'use strict';

// MODULES //

var FLOAT32_MAX_LN = require( '@stdlib/constants/float32/max-ln' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var exp = require( '@stdlib/math/base/special/exp' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var polyval = require( './polyval.js' );


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );
var HALF = f32( 0.5 );


// MAIN //

/**
* Computes the hyperbolic sine of a single-precision floating-point number.
*
* ## Method
*
* The range is partitioned into two segments. If \\( |x| \le 1 \\), we use a rational function of the form
*
* ```tex
* x + x^3 \frac{\mathrm{P}(x)}{\mathrm{Q}(x)}
* ```
*
* Otherwise, the calculation is
*
* ```tex
* \operatorname{sinhf}(x) = \frac{ e^x - e^{-x} }{2}.
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain   | # trials | peak    | rms     |
*     |:----------:|:--------:|:--------:|:-------:|:-------:|
*     | IEEE       | +-MAXLOG | 100000   | 1.1e-7  | 2.9e-8  |
*
* @param {number} x - input value
* @returns {number} hyperbolic sine
*
* @example
* var v = sinhf( 0.0 );
* // returns 0.0
*
* @example
* var v = sinhf( 2.0 );
* // returns ~3.627
*
* @example
* var v = sinhf( -2.0 );
* // returns ~-3.627
*
* @example
* var v = sinhf( NaN );
* // returns NaN
*/
function sinhf( x ) {
	var a;
	x = f32( x );

	// Handle NaN:
	if ( isnanf( x ) ) {
		return x;
	}
	if ( x === ZERO ) {
		return x;
	}
	a = ( x < ZERO ) ? -x : x;

	// Handle infinities & Check for overflow:
	if ( isInfinitef( x ) || a > FLOAT32_MAX_LN ) {
		return ( x > ZERO ) ? PINF : NINF;
	}

	if ( a > ONE ) {
		a = f32( exp( a ) );
		a = f32( ( HALF * a ) - (HALF / a) );
		if ( x < ZERO ) {
			a = -a;
		}
	}
	else {
		a = f32( x * x );
		a = f32( f32( polyval( a ) * a * x ) + x );
	}
	return a;
}


// EXPORTS //

module.exports = sinhf;
